package pl.com.coders.libria1.service;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.Optional;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import pl.com.coders.libria1.mapper.BookMapper;
import pl.com.coders.libria1.repository.BookRepository;

@ExtendWith(MockitoExtension.class)
class BookServiceTest {

    @Mock
    private BookRepository bookRepository;

    @Mock
    private BookMapper bookMapper;

    @InjectMocks
    private BookService bookService;

    // GreyTest trace: get | Optional.orElseThrow when no book is found | BR-002 -> TP-002 -> TC-010
    @Test
    void get_WhenBookIsMissing_ThrowsIllegalArgumentException() {
        // Arrange
        Long id = 1001L;
        when(bookRepository.findById(id)).thenReturn(Optional.empty());

        // Act
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> bookService.get(id));

        // Assert
        assertEquals("Book not exist with id : 1001", exception.getMessage());
        verify(bookRepository).findById(id);
        verify(bookMapper).toView(org.mockito.ArgumentMatchers.any());
    }
}
